from fractions import Fraction
from collections import deque

def solve():
    start_node = Fraction(11, 3)
    targets = [
        Fraction(7, 3),
        Fraction(11, 4),
        Fraction(2024, 5),
        Fraction(109, 11),
        Fraction(3, 71),
        Fraction(5, 204)
    ]

    excluded = {Fraction(0), Fraction(1, 2), Fraction(1), Fraction(-1)}

    distances = {start_node: 0}
    queue = deque([start_node])

    while queue:
        r = queue.popleft()
        d = distances[r]

        neighbors = []
        if r != 0:
            neighbors.append(-r)
        if r != Fraction(1, 2):
            neighbors.append(1 - r)
        if r != 0 and r != 1 and r != -1:
            neighbors.append(1 / r)

        for n in neighbors:
            if n not in excluded and n not in distances:
                distances[n] = d + 1
                queue.append(n)
                if n in targets:
                    pass

    results = []
    for t in targets:
        if t in distances:
            results.append((1 + distances[t]) % 2)
        else:
            results.append(None)

    print(f"Results: {results}")
    print(f"Sum: {sum(results)}")

solve()
